public static RMarketSignalLog find(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp,
    boolean             _forUpdate = false)
{
    RMarketSignalLog signalLog;

    signalLog.selectForUpdate(_forUpdate);

    if (_subAccountId && _actionRecId && _timestamp)
    {
        select firstonly signalLog
            where signalLog.SubAccountId               == _subAccountId
               && signalLog.RMarketStrategySignalRecId == _actionRecId
               && signalLog.Timestamp                  == _timestamp;
    }

    return signalLog;
}

public static boolean exists(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp)
{
    RMarketSignalLog signalLog = RMarketSignalLog::find(_subAccountId, _actionRecId, _timestamp);

    return signalLog.RecId != 0;
}

public static RMarketSignalLog putRecord(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp,
    RMarketSignalResult _result,
    str                 _description = "")
{
    RMarketSignalLog signalLog;

    ttsbegin;

    signalLog.clear();
    signalLog.initValue();

    signalLog.SubAccountId               = _subAccountId;
    signalLog.RMarketStrategySignalRecId = _actionRecId;
    signalLog.Timestamp                  = _timestamp;
    signalLog.Result                     = _result;
    signalLog.Description                = _description;

    if (signalLog.validateWrite())
        signalLog.insert();
    else
        throw error("Cannot write signal log.");

    ttscommit;

    return signalLog;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (ret && this.Result == RMarketSignalResult::None)
        ret = checkFailed("Signal result must be specified.");

    return ret;
}

public static RMarketSignalLog findCompleted(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp)
{
    RMarketSignalLog signalLog;

    select firstonly signalLog
        where signalLog.SubAccountId               == _subAccountId
           && signalLog.RMarketStrategySignalRecId == _actionRecId
           && signalLog.Timestamp                  == _timestamp
           && (signalLog.Result == RMarketSignalResult::Triggered
            || signalLog.Result == RMarketSignalResult::NotTriggered);

    return signalLog;
}

public static int64 countErrors(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp)
{
    RMarketSignalLog signalLog;

    select count(RecId) from signalLog
        where signalLog.SubAccountId               == _subAccountId
           && signalLog.RMarketStrategySignalRecId == _actionRecId
           && signalLog.Timestamp                  == _timestamp
           && signalLog.Result                     == RMarketSignalResult::Error;

    return signalLog.RecId;
}
